/**
 * Espera todas las extracciones en vuelo (incluidas las corridas
 * trailing guardadas) con un timeout suave. Lo llama print.ts después de
 * que la respuesta se descargó pero antes de gracefulShutdownSync. No hace
 * nada hasta que se llame initExtractMemories().
 */
export async function drainPendingExtraction(
  timeoutMs?: number,
  _

_signal?: AbortSignal): Promise<void> {
  const bindings = getMemoryHostBindings()
  const fs = bindings.getFsImplementation?.()
  if (!fs) return
  try {
    await fs.mkdir(memoryDir)
  } catch (e) {
    const code =
      e instanceof Error && 'code' in e && typeof e.code === 'string'
        ? e.code
        : undefined
    bindings.logDebug?.(
      `ensureMemoryDirExists failed for ${memoryDir}: ${code ?? String(e)}`,
      { level: 'debug' },
    )
  }
}

/**
 * Log memory directory file/subdir counts asynchronously.
 * Fire-and-forget — doesn't block prompt building.
 */
function logMemoryDirCounts(
  memoryDir: string,
  baseMetadata: Record<
    string,
    | number
    | boolean
    | AnalyticsMetadata_I_VERIFIED_THIS_IS_NOT_CODE_OR_FILEPATHS
  >,
): void {
  const bindings = getMemoryHostBindings()
  const fs = bindings.getFsImplementation?.()
  if (!fs) return
  void fs.readdir(memoryDir).then(
    dirents => {
      let fileCount = 0
      let subdirCount = 0
      for (const d of dirents) {
        if (d.isFile()) {
          fileCount++
        } else if (d.isDirectory()) {
          subdirCount++
        }
      }
      bindings.logEvent?.('tengu_memdir_loaded', {
        ...baseMetadata,
        total_file_count: fileCount,
        total_subdir_count: subdirCount,
      } as Record<string, number | boolean | string>)
    },
    () => {
      bindings.logEvent?.('tengu_memdir_loaded', baseMetadata as Record<string, number | boolean | string>)
    },
  )
}

